using AppCondominio.SharedKernel;
namespace AppCondominio.Modules.Governance.Domain;
public enum AssemblyStatus{Draft=0,Open=1,Closed=2,Cancelled=3} public enum VoteChoice{Yes=1,No=2,Abstain=3} public enum CoexistenceCaseStatus{Reported=0,UnderReview=1,Resolved=2,Dismissed=3}
public sealed class Assembly:AggregateRoot{private Assembly(Guid id,Guid communityId,string title,DateTimeOffset scheduledAt,decimal quorumPercent):base(id){CommunityId=communityId;Title=Req(title);ScheduledAt=scheduledAt;QuorumPercent=quorumPercent;}public Guid CommunityId{get;private set;}public string Title{get;private set;}public DateTimeOffset ScheduledAt{get;private set;}public decimal QuorumPercent{get;private set;}public AssemblyStatus Status{get;private set;}public int EligibleUnits{get;private set;}public int PresentUnits{get;private set;}public static Assembly Create(Guid communityId,string title,DateTimeOffset scheduledAt,decimal quorumPercent){if(communityId==Guid.Empty||quorumPercent<=0||quorumPercent>100)throw new ArgumentException("Invalid assembly.");return new(Guid.NewGuid(),communityId,title,scheduledAt,quorumPercent);}public void Open(int eligibleUnits,int presentUnits){if(Status!=AssemblyStatus.Draft||eligibleUnits<=0||presentUnits<0||presentUnits>eligibleUnits)throw new InvalidOperationException("Invalid assembly opening.");EligibleUnits=eligibleUnits;PresentUnits=presentUnits;if((decimal)presentUnits/eligibleUnits*100<QuorumPercent)throw new InvalidOperationException("Quorum not reached.");Status=AssemblyStatus.Open;}public void Close(){if(Status!=AssemblyStatus.Open)throw new InvalidOperationException("Only open assembly can close.");Status=AssemblyStatus.Closed;}static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed class Motion:AggregateRoot{private Motion(Guid id,Guid communityId,Guid assemblyId,string title):base(id){CommunityId=communityId;AssemblyId=assemblyId;Title=Req(title);}public Guid CommunityId{get;private set;}public Guid AssemblyId{get;private set;}public string Title{get;private set;}public int Yes{get;private set;}public int No{get;private set;}public int Abstain{get;private set;}public bool IsClosed{get;private set;}public bool IsApproved=>IsClosed&&Yes>No;public static Motion Create(Guid communityId,Guid assemblyId,string title)=>new(Guid.NewGuid(),communityId,assemblyId,title);public void RegisterVote(VoteChoice choice){if(IsClosed)throw new InvalidOperationException("Motion closed.");if(choice==VoteChoice.Yes)Yes++;else if(choice==VoteChoice.No)No++;else Abstain++;}public void Close()=>IsClosed=true;static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed class CoexistenceCase:AggregateRoot{private CoexistenceCase(Guid id,Guid communityId,Guid? propertyId,string category,string description,string reportedBy):base(id){CommunityId=communityId;PropertyId=propertyId;Category=Req(category);Description=Req(description);ReportedBy=Req(reportedBy);ReportedAtUtc=DateTimeOffset.UtcNow;}public Guid CommunityId{get;private set;}public Guid? PropertyId{get;private set;}public string Category{get;private set;}public string Description{get;private set;}public string ReportedBy{get;private set;}public DateTimeOffset ReportedAtUtc{get;private set;}public CoexistenceCaseStatus Status{get;private set;}public string? Resolution{get;private set;}public decimal PenaltyAmount{get;private set;}public string? BillingReference{get;private set;}public static CoexistenceCase Create(Guid communityId,Guid? propertyId,string category,string description,string reportedBy)=>communityId==Guid.Empty?throw new ArgumentException("Community required."):new(Guid.NewGuid(),communityId,propertyId,category,description,reportedBy);public void StartReview(){if(Status!=CoexistenceCaseStatus.Reported)throw new InvalidOperationException("Case cannot enter review.");Status=CoexistenceCaseStatus.UnderReview;}public void Resolve(string resolution,decimal penaltyAmount,string? billingReference){if(Status!=CoexistenceCaseStatus.UnderReview||penaltyAmount<0)throw new InvalidOperationException("Case cannot resolve.");Resolution=Req(resolution);PenaltyAmount=decimal.Round(penaltyAmount,2);BillingReference=string.IsNullOrWhiteSpace(billingReference)?null:billingReference.Trim();Status=CoexistenceCaseStatus.Resolved;}static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed record GovernanceKpi(int OpenAssemblies,int ApprovedMotions,int OpenCases,decimal ResolvedPenalties);